164	        {landing.length > 0 && <p className="text-xs text-muted-foreground">{landing.length === 1 ? "A transfer has" : `${landing.length} transfers have`} one side showing so far, so the total can run off by {money(landing.reduce((sum, item) => sum + (item.amountMinor < 0n ? -item.amountMinor : item.amountMinor), 0n), displayCurrency)} until the other lands. <Link href="/money/wealth" className="underline">See Wealth</Link></p>}
165	        {parts.transit !== 0n && <p className="text-xs text-muted-foreground">Includes {money(parts.transit, displayCurrency)} on its way between your accounts.</p>}
166	        {conflicted.length > 0 && <p className="text-xs text-warning">Two balances disagree for {conflicted.map(account => account.name).join(", ")}; using the most recently recorded one. <Link href="/money/accounts" className="underline">See both</Link></p>}
167	        {missingInputs.length > 0 && <details className={`text-xs ${convertedCount ? "text-warning" : "text-muted-foreground"}`}><summary className="cursor-pointer text-brand">{convertedCount ? `Not counted: ${missing.length === 1 ? "1 item" : `${missing.length} items`}` : "See what is missing"}</summary><ul className="mt-2 list-disc space-y-1 pl-4">{missing.map(item => <li key={item}>{item}</li>)}</ul><Link href="/money/accounts" className="mt-2 mr-3 inline-block underline">Review balances</Link><Link href="/money/wealth" className="mt-2 inline-block underline">Review dated valuations</Link></details>}
168	        {convertedCount > 0 && trend.length > 1 && <div><NetWorthChart label={`Net worth in ${displayCurrency} by day`}
169	            points={trend.map(point => ({ date: point.date, label: point.date === today ? `Today, ${fullDate(today)}` : fullDate(point.date), amount: money(point.value, displayCurrency), y: Number(point.value), uncertain: point.uncertain }))} />
170	          <p className="mt-2 flex justify-between font-mono text-[11px] text-subtle"><span>{monthLabel(trend[0].date)}</span>{trend.length > 2 && <span>{monthLabel(trend[Math.floor(trend.length / 2)].date)}</span>}<span>{monthLabel(today)}</span></p></div>}
171	        {convertedCount > 0 && <dl className="grid grid-cols-1 gap-px overflow-hidden rounded-[14px] bg-border sm:grid-cols-3">
172	          {([["Accounts", parts.cash, "/money/accounts"], ["Investments & assets", parts.assets, "/money/wealth"], ["Debts", parts.debts, "/money/wealth"]] as const).map(([label, amount, href]) =>
173	            <div key={label} className="bg-card"><Link href={href} className="flex flex-col gap-1 px-4 py-3.5 hover:bg-muted"><dt className="text-xs text-muted-foreground">{label}</dt><dd className="font-mono">{money(amount, displayCurrency)}</dd></Link></div>)}
174	        </dl>}
175	    </section>;
176	  }
177	
178	  async function homeAccounts() {
179	    const [accounts, balanceEvidence, bankAccounts] = await Promise.all([
180	      accountsPromise, balanceEvidencePromise, supabase.from("bank_connection_accounts").select("account_name, currency_code").eq("workspace_id", workspace.id),
181	    ]);
182	    if (bankAccounts.error) throw bankAccounts.error;
183	    const synced = new Set((bankAccounts.data ?? []).map(connected => JSON.stringify([connected.account_name, connected.currency_code])));
184	    const ago = (iso: string) => display.ago(iso, balanceEvidence.asOf);
185	    return <section aria-labelledby="home-accounts" className={card}>
186	      <div className="flex flex-wrap items-center justify-between gap-2"><h2 id="home-accounts" className="text-sm font-medium"><Link href="/money/accounts" className="hover:underline">Accounts</Link></h2>
187	        <div className="flex gap-2"><Link href="/import" className="rounded-lg border border-input px-2.5 py-1 text-xs hover:bg-muted">Import file</Link><Link href="/import#connected-banks" className="rounded-lg border border-input px-2.5 py-1 text-xs hover:bg-muted">Connect bank</Link></div></div>
188	      {!accounts.length && <p className="mt-3 text-sm text-muted-foreground">No accounts yet. <Link className="text-brand underline" href="/import">Import a statement</Link> or <Link className="text-brand underline" href="/money/accounts">add one</Link>.</p>}
189	      <ul className="mt-3 divide-y divide-border border-t border-border">{accounts.map(account => { const { balance } = account; const isSynced = synced.has(JSON.stringify([account.name, account.currency_code])); return <li key={account.id}><article className="flex flex-wrap items-center gap-x-3 gap-y-1 py-3">
190	        <span aria-hidden="true" className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-muted text-xs font-semibold">{account.name.trim().charAt(0).toUpperCase()}</span>
191	        <div className="min-w-0 flex-1"><h3 title={account.name} className="line-clamp-2 break-words text-sm font-medium">{account.name}</h3><p className="flex items-center gap-1.5 truncate text-xs text-muted-foreground"><span className="rounded border border-input px-1 font-mono text-[9px] uppercase">{isSynced ? "Bank" : "Manual"}</span>{balance.as_of ? `${isSynced ? "synced" : "set"} ${ago(balance.as_of)}` : "Add a dated balance"}</p></div>
192	        {(({ amount, label }) => <p className="ml-auto whitespace-nowrap text-right font-mono text-sm tabular-nums">{amount !== null ? money(amount, account.currency_code) : "Balance unknown"}{label !== "Current" && amount !== null && <span className="block font-sans text-[11px] text-muted-foreground">{balance.amount_minor === null ? `${label} · not in total` : label}</span>}</p>)(shownBalance(balance))}
193	        {!isSynced && <details className="w-full [&:not([open])]:-mt-1"><summary className="cursor-pointer text-xs font-medium text-brand hover:underline">Update balance</summary><div className="mt-2 rounded-lg border border-border p-3"><ManualBalanceForm account={account} snapshots={balanceEvidence.snapshots} ledger={balanceEvidence.ledger} asOf={balanceEvidence.asOf} timeZone={workspace.timezone} locale={locale} /></div></details>}
194	        {balance.warnings.length > 0 && <p className="w-full text-xs text-warning">{balance.warnings.join("; ")}</p>}
195	        {balance.status === "stale" && balance.snapshot_amount_minor !== null && <p className="w-full text-xs text-muted-foreground">Last set to {money(balance.snapshot_amount_minor, balance.currency_code)}, plus activity recorded since. Update the balance to confirm.</p>}
196	      </article></li>; })}</ul>
