200	  async function homeUpcoming(plan: NonNullable<typeof projection>) {
201	    const [projection, accountNames, priceChanges] = await Promise.all([plan, accountNamesPromise, loadPriceChanges(supabase, workspace.id).catch(upcomingEventsShowNoPriceChangeWhenLookupFails)]);
202	    const dateTile = (date: string) => ({ month: display.shortMonth(date), day: date.slice(8, 10) });
203	
204	    const upcoming = (projection.input?.events ?? []).filter(event => event.expectedMinor < 0n && event.source !== "estimated").sort((a, b) => a.date.localeCompare(b.date));
205	    const upcomingMinor = upcoming.reduce((sum, event) => sum + event.expectedMinor, 0n);
