219	    const [projection, accountNames] = await Promise.all([plan, accountNamesPromise]);
220	    return projection.liquidity && <section aria-label="Available funds"><HomeLiquidity liquidity={projection.liquidity} accountId={accountId} names={accountNames} locale={locale} coverage={<SourceCoverageDetails coverage={projection.sourceCoverage} locale={locale} />} /></section>;
221	  }
