238	  async function homeInsights(plan: NonNullable<typeof projection>, evidence: NonNullable<typeof insightEvidence>) {
239	    const [projection, { missingInputs }, names, wealth] = await Promise.all([plan, convertedPromise, accountNamesPromise, wealthPromise]);
240	    return <WeeklyBriefing {...sectionProps} settings={context.settings} projection={projection} missingInputs={missingInputs} names={names} wealth={wealth} evidence={evidence} />;
241	  }
242	
243	  const widgets: Record<string, () => ReactNode> = {
244	    ...Object.fromEntries([...cards.values()].map(row => [`card:${row.id}`, () => <Suspense key={row.id} fallback={<CardSkeleton title={row.title} />}>
245	      <HomeCard card={row} context={context} shared={shared} open={`/ai/artifacts/${row.artifact_id}?tab=cards`} />
246	    </Suspense>])),
247	    spending: () => <Suspense fallback={<SectionFallback title="Cash flow · 6 months" chart={240} />}>{spending && <CashFlowPanel data={spending} currency={displayCurrency} locale={locale} />}</Suspense>,
248	    recent: () => <Suspense fallback={<SectionFallback title="Recent transactions" />}><RecentTransactions db={supabase} workspaceId={workspace.id} locale={locale} names={accountNamesPromise} /></Suspense>,
249	    planning: () => <Suspense fallback={<SectionFallback title="Available funds" />}>{projection && awaitedLater(homePlanning(projection))}</Suspense>,
250	    accounts: () => <Suspense fallback={<SectionFallback title="Accounts" />}>{awaitedLater(homeAccounts())}</Suspense>,
251	    upcoming: () => <Suspense fallback={<SectionFallback title="Coming up" />}>{projection && awaitedLater(homeUpcoming(projection))}</Suspense>,
252	    history: () => <Suspense fallback={null}><HomeHistory db={supabase} workspaceId={workspace.id} locale={locale} timeZone={workspace.timezone} names={accountNamesPromise} /></Suspense>,
253	    budgets: () => <Suspense fallback={<SectionFallback title="Budgets" />}>{insightEvidence && <HomeBudgets evidence={insightEvidence} currency={displayCurrency} today={today} locale={locale} />}</Suspense>,
254	    goals: () => <Suspense fallback={<SectionFallback title="Goals" />}>{awaitedLater(homeGoals())}</Suspense>,
255	    agents: () => <Suspense fallback={<SectionFallback title="Agent team" />}><AgentBriefing db={supabase} workspaceId={workspace.id} timeZone={workspace.timezone} ai={aiPromise} /></Suspense>,
256	    insights: () => <Suspense fallback={<SectionFallback title="Weekly briefing" />}>{projection && insightEvidence && awaitedLater(homeInsights(projection, insightEvidence))}</Suspense>,
257	  };
258	  const overview = ordered.includes("overview") ? awaitedLater(homeOverview()) : null;
259	  const visibleWidgets = Object.fromEntries(ordered.filter(key => key !== "overview").map(key => [key, widgets[key]()]));
260	  if (overview) visibleWidgets.overview = await overview;
261	
262	  return <>
263	    {steps.show && <FirstSteps steps={steps} />}
264	    <Suspense fallback={null}>{notices}</Suspense>
265	    <HomeGrid editable={steps.canCustomize} version={saved.version} items={ordered} sizes={sizes} labels={labels} options={Object.fromEntries(keys.map(key => [key, sizeOptions(key)]))}
266	      widgets={visibleWidgets} />
267	  </>;
268	}
