270	async function HomeAttention({ waiting, review, locale }: { waiting: ReturnType<typeof loadWaitingForYou>; review: ReturnType<typeof loadReview>; locale: string }) {
271	  const [proposals, summary] = await Promise.all([waiting, review]);
272	  return <WaitingForYou proposals={proposals} review={summary} locale={locale} />;
273	}
