215	    onDragOver: ({ active, over }) => over ? `${name(active.id)} is at position ${shown.indexOf(String(active.id)) + 1} of ${shown.length}.` : undefined,
216	    onDragEnd: ({ active }) => `${name(active.id)} dropped at position ${shown.indexOf(String(active.id)) + 1}.`,
217	    onDragCancel: ({ active }) => `Moving ${name(active.id)} was cancelled.`,
218	  };
219	
220	  return <DndContext id="home-grid" sensors={sensors} autoScroll={autoScroll} collisionDetection={nearestWidget} onDragStart={dragStart} onDragMove={dragMove} onDragEnd={dragEnd} onDragCancel={() => dragEnd(null)}
221	    accessibility={{ announcements, screenReaderInstructions: { draggable: "Use the arrow keys to move this widget one place at a time." } }}>
222	    {editable && <div className="flex flex-wrap items-center justify-end gap-x-3 gap-y-1">
223	      {customizing && <p className="mr-auto text-sm text-muted-foreground">Drag a widget by its handle, or focus the handle and use the arrow keys. On a phone, hold a widget to drag it.</p>}
224	      {hidden.length > 0 && <div className="relative">
225	        <button type="button" aria-expanded={menu} onClick={() => setMenu(open => !open)}
226	          className="flex min-h-11 items-center gap-1.5 rounded-lg border border-input px-3 text-sm font-medium text-muted-foreground hover:bg-muted hover:text-foreground lg:min-h-9">
227	          <Plus className="size-4" aria-hidden="true" />Add widget</button>
228	        {menu && <ul aria-label="Hidden widgets" className="absolute top-full right-0 z-20 mt-2 w-max min-w-56 overflow-hidden rounded-xl border border-border bg-card py-1 shadow-lg">
229	          {hidden.map(key => <li key={key}><button type="button" onClick={() => add(key)} className="block w-full px-4 py-2.5 text-left text-sm hover:bg-muted">{labels[key]}</button></li>)}
230	        </ul>}
231	      </div>}
232	      <button type="button" aria-pressed={customizing} onClick={() => { setCustomizing(on => !on); setMenu(false); }} className="min-h-11 rounded-lg px-3 text-sm font-medium text-muted-foreground hover:bg-muted hover:text-foreground lg:min-h-9">{customizing ? "Done" : "Customize"}</button>
233	    </div>}
234	    <SortableContext items={shown} strategy={stay}>
235	      <div ref={grid} className="grid items-start gap-4 lg:grid-flow-row-dense lg:grid-cols-6 lg:data-masonry:auto-rows-[4px] lg:data-masonry:gap-y-0 lg:data-masonry:[&>*]:[grid-row-end:span_var(--rows,1)]">
236	        {shown.map(key => {
237	          const size = resizing?.key === key ? resizing.size : layout.sizes[key] ?? "M";
238	          return <Widget key={key} id={key} label={labels[key] ?? "Widget"} size={size} lifted={drag?.id === key} options={options[key] ?? []} selected={selected === key || customizing} resizing={resizing?.key === key}
239	            onHide={() => hide(key)} onMoveKey={event => moveKey(key, event)} onResizeStart={event => startResize(key, event)} onResizeKey={event => resizeKey(key, event)}>
240	            <HomeCardSize.Provider value={layout.sizes[key] ?? null}>{widgets[key] ?? <SectionFallback title={labels[key] ?? "Widget"} />}</HomeCardSize.Provider>
241	          </Widget>;
242	        })}
243	      </div>
244	    </SortableContext>
245	    <DragOverlay dropAnimation={{ duration: 200, easing: "cubic-bezier(.2,.8,.2,1)" }}>
246	      {drag && <div ref={node => { if (node && !node.firstChild) node.append(drag.clone); }} style={{ width: drag.width, height: drag.height }}
247	        className="pointer-events-none rotate-[0.6deg] scale-[1.02] cursor-grabbing rounded-2xl shadow-2xl ring-1 ring-border [&>*]:h-full [&>*>section]:h-full" />}
248	    </DragOverlay>
249	    <p aria-live="polite" className="sr-only">{said}</p>
250	    {notice && <div role="status" className="fixed inset-x-0 bottom-[calc(5rem+env(safe-area-inset-bottom))] z-50 lg:bottom-6 mx-auto flex w-fit max-w-[calc(100%-2rem)] items-center gap-4 rounded-xl bg-foreground px-4 py-3 text-sm text-background shadow-lg">
251	      <span>{notice.text}</span>
252	      {notice.action && <button type="button" onClick={notice.action.run} className="font-medium underline-offset-2 hover:underline">{notice.action.label}</button>}
253	      {notice.action && <button type="button" aria-label="Dismiss" onClick={() => setNotice(null)} className="-mr-1 rounded p-1 hover:bg-background/20"><X className="size-4" aria-hidden="true" /></button>}
254	    </div>}
255	  </DndContext>;
256	}
257	
258	type WidgetProps = { id: string; label: string; size: CardSize; lifted: boolean; options: CardSize[]; selected: boolean; resizing: boolean; children: ReactNode;
259	  onHide: () => void; onMoveKey: (event: KeyboardEvent) => void; onResizeStart: (event: ReactPointerEvent<HTMLElement>) => void; onResizeKey: (event: KeyboardEvent) => void };
260	
261	function Widget({ id, label, size, lifted, options, selected, resizing, children, onHide, onMoveKey, onResizeStart, onResizeKey }: WidgetProps) {
262	  const { setNodeRef, setActivatorNodeRef, listeners, attributes } = useSortable({ id });
263	  const { onTouchStart, onMouseDown } = (listeners ?? {}) as Record<string, (event: SyntheticEvent) => void>;
264	  const tools = `transition-opacity ${lifted ? "invisible" : selected || resizing ? "opacity-100" : "opacity-0 group-hover:opacity-100 focus-within:opacity-100"}`;
265	  return <div ref={setNodeRef} data-widget={id} onTouchStart={onTouchStart} onMouseDown={event => { if (dragsWidget(event.target)) onMouseDown?.(event); }}
266	    className={`group relative min-w-0 ${CARD_SIZES[size].span} [&:has(>[data-tools]:first-child)]:hidden touch-manipulation [-webkit-touch-callout:none] pointer-coarse:select-none [&>section]:h-full [&_h2]:cursor-grab [&_h3:first-child]:cursor-grab ${lifted ? "rounded-2xl bg-muted/50 outline-2 outline-offset-0 outline-dashed outline-input [&>*]:opacity-0" : ""} ${selected ? "rounded-2xl outline-2 outline-brand" : ""}`}>
267	    {children}
268	    <div data-tools className={`absolute -top-3 left-1/2 z-10 flex -translate-x-1/2 items-center rounded-full border border-border bg-card shadow-sm ${tools}`}>
269	      <button type="button" ref={setActivatorNodeRef} {...attributes} aria-label={`Move ${label}`} data-grip title="Drag to move" onMouseDown={onMouseDown} onKeyDown={onMoveKey}
270	        className="flex h-7 cursor-grab items-center rounded-l-full px-2.5 pointer-coarse:h-11 pointer-coarse:px-4 text-muted-foreground hover:text-foreground active:cursor-grabbing"><GripHorizontal className="size-4" aria-hidden="true" /></button>
271	      <button type="button" aria-label={`Hide ${label}`} title="Hide" onClick={onHide}
272	        className="flex h-7 items-center rounded-r-full border-l border-border px-2 pointer-coarse:h-11 pointer-coarse:px-4 text-muted-foreground hover:text-foreground"><X className="size-3.5" aria-hidden="true" /></button>
273	    </div>
274	    {options.length > 1 && <button type="button" aria-label={`Resize ${label}, now ${size}`} title="Drag to resize" onPointerDown={onResizeStart} onKeyDown={onResizeKey}
275	      className={`absolute top-1/2 -right-2 z-10 hidden h-12 w-4 -translate-y-1/2 cursor-ew-resize touch-none items-center justify-center lg:flex ${tools}`}>
276	      <span className="h-10 w-1.5 rounded-full bg-input group-hover:bg-muted-foreground/60" aria-hidden="true" /></button>}
277	  </div>;
278	}
