cat > .qa/seed-home.mjs <<'EOF'
import postgres from "postgres";
import { compileCard } from "../lib/cards/sandbox.ts";
process.loadEnvFile(".env.qa");
const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} });
const [{ id: ws }] = await db`select w.id from public.workspaces w join auth.users u on u.id = w.owner_id where u.email = ${process.env.E2E_USER_EMAIL}`;
const CARD = `export default function Card({ data, size }) {
  return <div style={{ display: "grid", gap: 8 }}><p style={{ fontSize: 28, fontWeight: 600 }}>Accounts {data.accounts.length}</p><p>Size {size}</p></div>;
}`;
const names = ["Main checking", "Joint checking", "Savings", "Holiday pot", "Credit card", "Travel card", "Emergency fund", "Kids savings", "Business", "Tax reserve", "Cash wallet", "Old bank"];
const merchants = ["Rewe", "Lidl", "Aldi", "Edeka", "Amazon", "Netflix", "Spotify", "Deutsche Bahn", "Shell", "Ikea", "Zalando", "Apotheke", "Bakery", "Restaurant", "Cinema", "Gym", "Uber", "Lufthansa", "DM", "Mediamarkt"];
await db.begin(async tx => {
  const accounts = [];
  for (const [i, name] of names.entries()) {
    const [a] = await tx`insert into public.accounts (workspace_id, name, type, currency_code) values (${ws}, ${name}, ${i === 4 || i === 5 ? "credit_card" : i % 3 === 2 ? "savings" : "checking"}, 'EUR') returning id`;
    accounts.push(a.id);
    await tx`insert into public.balance_snapshots (workspace_id, account_id, amount_minor, currency_code, as_of, provenance) values (${ws}, ${a.id}, ${(100000 + i * 73519) * (i === 4 ? -1 : 1)}, 'EUR', now() - interval '400 days', 'manual')`;
    await tx`insert into public.balance_snapshots (workspace_id, account_id, amount_minor, currency_code, as_of, provenance) values (${ws}, ${a.id}, ${(120000 + i * 81237) * (i === 4 ? -1 : 1)}, 'EUR', now() - interval '2 days', 'manual')`;
  }
  const rows = [];
  for (let n = 0; n < 6000; n++) {
    const account = accounts[n % 7 === 0 ? 1 : n % 11 === 0 ? 4 : 0];
    const day = Math.floor(n * 450 / 6000);
    const salary = n % 200 === 0;
    rows.push({ workspace_id: ws, account_id: account, posted_on: new Date(Date.now() - day * 86400000).toISOString().slice(0, 10),
      description: salary ? "Salary ACME GmbH" : `${merchants[n % merchants.length]} ${1000 + (n % 97)}`, amount_minor: salary ? 420000 : -(300 + ((n * 7919) % 12000)), currency_code: "EUR" });
  }
  for (let i = 0; i < rows.length; i += 1000) await tx`insert into public.transactions ${tx(rows.slice(i, i + 1000))}`;
  const [{ id: artifact }] = await tx`insert into public.artifacts (workspace_id, title) values (${ws}, 'Seeded artifact') returning id`;
  const queries = tx.json([{ name: "accounts", source: "accounts", input: {} }]);
  await tx`insert into public.artifact_versions (workspace_id, artifact_id, version, prompt, html, queries) values (${ws}, ${artifact}, 1, 'Count', '<html><body>Seeded</body></html>', ${queries})`;
  const [{ id: card }] = await tx`insert into public.artifact_cards (workspace_id, artifact_id, title, size, published_version) values (${ws}, ${artifact}, 'Seeded card', 'M', 1) returning id`;
  await tx`insert into public.artifact_card_versions (workspace_id, card_id, version, title, kind, source, compiled, queries, params, prompt) values (${ws}, ${card}, 1, 'Seeded card', 'code', ${CARD}, ${compileCard(CARD)}, ${queries}, '[]', 'Count')`;
  const items = ["overview", `card:${card}`, "insights", "upcoming", "spending", "budgets", "accounts", "recent", "agents", "history", "goals"];
  await tx`insert into public.dashboard_layouts (workspace_id, items, sizes) values (${ws}, ${items}, ${tx.json({ accounts: "L", recent: "M", upcoming: "M" })})
    on conflict (workspace_id) do update set items = excluded.items, sizes = excluded.sizes, version = dashboard_layouts.version + 1`;
});
const [counts] = await db`select (select count(*) from public.accounts where workspace_id=${ws}) a, (select count(*) from public.transactions where workspace_id=${ws}) t`;
console.log(counts);
await db.end();
EOF
npm run qa:reset 2>&1 | tail -1 && node --experimental-strip-types .qa/seed-home.mjs

