import { chromium } from "@playwright/test";
const [base = "http://localhost:3101", runs = "5", width = "1280", height = "720", path = "/"] = process.argv.slice(2);
const browser = await chromium.launch();
const totals = [];
for (let run = 0; run < Number(runs); run++) {
  const context = await browser.newContext({ baseURL: base, storageState: "e2e/.auth.json", viewport: { width: Number(width), height: Number(height) }, extraHTTPHeaders: { "x-moneo-test": "1" } });
  await context.addInitScript(() => {
    const describe = node => { if (!node) return "?"; const el = node.nodeType === 1 ? node : node.parentElement; if (!el) return "#text"; const w = el.closest("[data-widget]")?.getAttribute("data-widget"); const s = el.closest("section")?.getAttribute("aria-label") ?? el.closest("section")?.querySelector("h2")?.textContent; return `${el.tagName.toLowerCase()}${el.id ? "#" + el.id : ""}.${String(el.className).slice(0, 60)} widget=${w ?? "-"} section=${s ?? "-"}`; };
    window.__shifts = [];
    window.__h = 0;
    const tick = () => { const h = document.querySelector("main h1"); if (h) window.__h = performance.now(); else requestAnimationFrame(tick); }; requestAnimationFrame(tick);
    new PerformanceObserver(list => { for (const e of list.getEntries()) if (!e.hadRecentInput) window.__shifts.push({ t: Math.round(e.startTime), v: +e.value.toFixed(4), sources: e.sources.map(s => ({ node: describe(s.node), from: [s.previousRect.y, s.previousRect.height].map(Math.round), to: [s.currentRect.y, s.currentRect.height].map(Math.round) })) }); }).observe({ type: "layout-shift", buffered: true });
    window.__lcp = 0; new PerformanceObserver(list => { for (const e of list.getEntries()) window.__lcp = e.startTime; }).observe({ type: "largest-contentful-paint", buffered: true });
  });
  const page = await context.newPage();
  await page.goto(path);
  await page.locator("main h1").first().waitFor();
  await page.waitForLoadState("networkidle");
  await page.waitForTimeout(1000);
  const r = await page.evaluate(() => ({ shifts: window.__shifts, h: window.__h, lcp: window.__lcp, nav: performance.getEntriesByType("navigation")[0].responseStart }));
  const total = r.shifts.reduce((s, e) => s + e.v, 0);
  totals.push(total);
  console.log(`run ${run} cls ${total.toFixed(3)} heading ${r.h.toFixed(0)} lcp ${r.lcp.toFixed(0)} ttfb ${r.nav.toFixed(0)}`);
  if (process.env.VERBOSE) for (const s of r.shifts) console.log(JSON.stringify(s));
  await context.close();
}
totals.sort((a, b) => a - b);
console.log("median cls", totals[Math.floor(totals.length / 2)].toFixed(3));
await browser.close();
EOF
